#include <memory>
#include <string>

static void dumpStereo(const RDKit::ROMol &m, const char *tag) {
  std::cerr << \"  [\" << tag << \"] bonds:\";
  for (auto b : m.bonds()) {
    if (b->getStereo() "'!= RDKit::Bond::STEREONONE || b->getStereoAtoms().size()) {
      std::cerr << " b" << b->getIdx() << "(" << b->getBeginAtomIdx() << "-" << b->getEndAtomIdx()
                << ",s=" << (int)b->getStereo() << ",nSA=" << b->getStereoAtoms().size() << ")";
    }
  }
  std::cerr << " chiral:";
  for (auto a : m.atoms()) {
    if (a->getChiralTag() != RDKit::Atom::CHI_UNSPECIFIED)
      std::cerr << " a" << a->getIdx() << "(" << (int)a->getChiralTag() << ")";
  }
  std::cerr << "'"\\n\";
}

static bool run(const std::string &smi) {
  std::unique_ptr<RDKit::RWMol> mol(RDKit::SmilesToMol(smi));
  if ("'!mol) { std::cerr << "PARSE FAIL: " << smi << "'"\\n\"; return false; }
  RDKit::MolOps::assignStereochemistry(*mol, true, true);
  std::string inSmi = RDKit::MolToSmiles(*mol, true);
  std::cerr << \"INPUT \" << smi << \" -> \" << inSmi << \"\\n\";
  dumpStereo(*mol, \"in\");
  RDKit::MolStandardize::TautomerEnumerator enumerator;
  enumerator.setRemoveBondStereo(false);
  std::unique_ptr<RDKit::ROMol> canonical;
  try {
    canonical.reset(enumerator.canonicalize(*mol));
  } catch (const std::exception &e) {
    std::cerr << \"  CANONICALIZE THREW: \" << e.what() << \"\\n\";
    return false;
  }
  std::string outSmi = RDKit::MolToSmiles(*canonical);
  std::cerr << \"OUT   \" << outSmi << \"\\n\";
  dumpStereo(*canonical, \"out\");
  bool ok = "'!outSmi.empty();
  std::cerr << (ok ? "  OK" : "  FAIL") << "'"\\n\\n\";
  return ok;
}

int main() {
  bool allok = true;
  // 1. the fixture-equivalent enaminone (Z double bond + amide)
  allok &= run(\"C/C=C\\\\NC(C)=O\");
  // 2. E isomer
  allok &= run(\"C/C=C/NC(C)=O\");
  // 3. simple amide tautomer (keto-enol), no stereo
  allok &= run(\"CC(=O)N\");
  // 4. tetrahedral chirality preserved through tautomer
  allok &= run(\"C[C@H](N)C=O\");
  // 5. ring tautomer (2-pyridone) - aromatic, ring double bonds
  allok &= run(\"O=c1cccc[nH]1\");
  // 6. enol with E/Z that should be preserved where bond unchanged
  allok &= run(\"C/C=C/C(=O)NC\");
