  allok &= run(\"C/C=C\\\\C(O)=NC\");
  // 8. imidic-acid-like with atropisomer-encoded wedge via mol? use smiles dir
  allok &= run(\"C/C=C\\\\NC(/C)=O\");
  std::cout << (allok ? \"ALL_OK\" : \"SOME_FAILED\") << \"\\n\";
  return allok ? 0 : 1;
}
